#include "dei_out_private.h"
/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/
static void dei_out_faa_door_skip_enter( void );
static void dei_out_faa_door_skip_leave( Boolean status );
/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/


//--------------------------------------------------------------------------//

void dei_out_factory_alarm_arm( void *payload)
{
    DEI_OUT_FACTORY_ALARM_ARM_RESET();
	DEI_OUT_FACTORY_ALARM_DISARM_RESET();

    dei_out_faa_door_skip_enter();    
	
	DEI_OUT_FACTORY_ALARM_ARM( 0 , 80 , 1 , 1 ) ;	
}

//--------------------------------------------------------------------------//

void dei_out_faa_door_skip_enter( void )
{
    PER_EXEC_ATOMIC( out_q_remove( out_q_main , (Out_Func)dei_out_faa_door_skip_leave , TRUE ) );

    set_door_skip();

    TRACE_DEI_OUT("[DOOR_SKIP_ENTER]\n\r");

    PER_EXEC_ATOMIC( out_q_insert( out_q_main , (Out_Func)dei_out_faa_door_skip_leave , 90,1,1,1));
}

//--------------------------------------------------------------------------//

void dei_out_faa_door_skip_leave( Boolean status )
{
    if( status )
    {
        clr_door_skip() ; 

        TRACE_DEI_OUT("[DOOR_SKIP_LEAVE]\n\r");
    }
}    

//--------------------------------------------------------------------------//

